<?php
require_once __DIR__ . '/auth.php';
$message = '';
$edit = null;
if (isset($_GET['action'], $_GET['id']) && $_GET['action'] === 'edit') {
    $stmt = $pdo->prepare('SELECT * FROM discounts WHERE id = ?');
    $stmt->execute([(int)$_GET['id']]);
    $edit = $stmt->fetch();
}
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    verifyCsrfToken();
    $id = filter_input(INPUT_POST, 'id', FILTER_VALIDATE_INT);
    $action = isset($_POST['action']) ? $_POST['action'] : '';
    if ($action === 'delete' && $id) {
        requireAdminRole('super_admin');
        $stmt = $pdo->prepare('SELECT usage_count FROM discounts WHERE id = ?'); $stmt->execute([$id]);
        $count = (int)$stmt->fetchColumn();
        if ($count > 0) $message = 'Impossible : ce code a déjà été utilisé ' . $count . ' fois.';
        else { $pdo->prepare('DELETE FROM discounts WHERE id = ?')->execute([$id]); $message = 'Code promo supprimé.'; }
    } elseif ($action === 'toggle' && $id) {
        $pdo->prepare('UPDATE discounts SET is_active = 1 - is_active WHERE id = ?')->execute([$id]);
    } elseif ($action === 'save') {
        $code = strtoupper(trim(isset($_POST['code']) ? $_POST['code'] : ''));
        $type = isset($_POST['type']) && $_POST['type'] === 'fixed' ? 'fixed' : 'percentage';
        $value = filter_var(isset($_POST['value']) ? $_POST['value'] : '', FILTER_VALIDATE_FLOAT);
        $minimum = trim(isset($_POST['min_purchase_amount']) ? $_POST['min_purchase_amount'] : '') === '' ? null : filter_var($_POST['min_purchase_amount'], FILTER_VALIDATE_FLOAT);
        $limit = trim(isset($_POST['usage_limit']) ? $_POST['usage_limit'] : '') === '' ? null : filter_var($_POST['usage_limit'], FILTER_VALIDATE_INT);
        $from = isset($_POST['valid_from']) ? $_POST['valid_from'] : ''; $until = isset($_POST['valid_until']) ? $_POST['valid_until'] : '';
        if (!preg_match('/^[A-Z0-9_-]{3,50}$/', $code) || $value === false || $value <= 0 || ($type === 'percentage' && $value > 100) || $minimum === false || $limit === false || !$from || !$until || $from > $until) $message = 'Données de promotion invalides.';
        else try { if ($id) $pdo->prepare('UPDATE discounts SET code=?, type=?, value=?, min_purchase_amount=?, usage_limit=?, valid_from=?, valid_until=? WHERE id=?')->execute([$code,$type,$value,$minimum,$limit,$from,$until,$id]); else $pdo->prepare('INSERT INTO discounts (code,type,value,min_purchase_amount,usage_limit,valid_from,valid_until) VALUES (?,?,?,?,?,?,?)')->execute([$code,$type,$value,$minimum,$limit,$from,$until]); $message = 'Code promo enregistré.'; } catch (Exception $error) { $message = 'Ce code promo existe déjà.'; }
    }
}
$discounts = $pdo->query('SELECT * FROM discounts ORDER BY id DESC')->fetchAll();
?><!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Codes promo | Woodin Admin</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/css/bootstrap.min.css" rel="stylesheet"></head><body><main class="container py-4"><h1>Codes promo</h1><?php if ($message): ?><div class="alert alert-info"><?= e($message) ?></div><?php endif; ?><form method="post" class="row g-2 mb-4"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?= (int)($edit ? $edit['id'] : 0) ?>"><div class="col-md-2"><input class="form-control" name="code" placeholder="WOODIN10" required value="<?= e($edit ? $edit['code'] : '') ?>"></div><div class="col-md-2"><select class="form-select" name="type"><option value="percentage" <?= $edit && $edit['type'] === 'percentage' ? 'selected' : '' ?>>Pourcentage</option><option value="fixed" <?= $edit && $edit['type'] === 'fixed' ? 'selected' : '' ?>>Montant fixe</option></select></div><div class="col-md-2"><input class="form-control" name="value" type="number" min=".01" step=".01" required value="<?= e($edit ? $edit['value'] : '') ?>"></div><div class="col-md-2"><input class="form-control" name="min_purchase_amount" type="number" min="0" step=".01" value="<?= e($edit && $edit['min_purchase_amount'] !== null ? $edit['min_purchase_amount'] : '') ?>"></div><div class="col-md-2"><input class="form-control" name="usage_limit" type="number" min="1" value="<?= e($edit && $edit['usage_limit'] !== null ? $edit['usage_limit'] : '') ?>"></div><div class="col-md-2"><input class="form-control" name="valid_from" type="date" required value="<?= e($edit ? $edit['valid_from'] : '') ?>"></div><div class="col-md-2"><input class="form-control" name="valid_until" type="date" required value="<?= e($edit ? $edit['valid_until'] : '') ?>"></div><div class="col-md-2"><button class="btn btn-warning" type="submit"><?= $edit ? 'Modifier' : 'Créer' ?></button></div></form><table class="table"><thead><tr><th>Code</th><th>Réduction</th><th>Période</th><th>Utilisations</th><th>État</th><th>Actions</th></tr></thead><tbody><?php foreach ($discounts as $discount): ?><tr><td><?= e($discount['code']) ?></td><td><?= e($discount['value']) ?> <?= $discount['type'] === 'percentage' ? '%' : 'FCFA' ?></td><td><?= e($discount['valid_from']) ?> au <?= e($discount['valid_until']) ?></td><td><?= (int)$discount['usage_count'] ?></td><td><?= $discount['is_active'] ? 'Actif' : 'Inactif' ?></td><td><a class="btn btn-sm btn-outline-dark" href="?action=edit&amp;id=<?= (int)$discount['id'] ?>">Modifier</a><form method="post" class="d-inline"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?= (int)$discount['id'] ?>"><button class="btn btn-sm btn-outline-secondary">Activer</button></form><?php if ((isset($_SESSION['admin_role']) ? $_SESSION['admin_role'] : '') === 'super_admin'): ?><button class="btn btn-sm btn-outline-danger" data-bs-toggle="modal" data-bs-target="#deleteModal" data-item-id="<?= (int)$discount['id'] ?>" data-item-name="<?= e($discount['code']) ?>">Supprimer</button><?php endif; ?></td></tr><?php endforeach; ?></tbody></table><div class="modal fade" id="deleteModal" tabindex="-1"><div class="modal-dialog"><div class="modal-content"><div class="modal-header bg-danger text-white"><h5>Confirmer la suppression</h5></div><div class="modal-body">Supprimer <strong id="deleteItemName"></strong> ? Cette action est irréversible.</div><div class="modal-footer"><button class="btn btn-secondary" data-bs-dismiss="modal">Annuler</button><form method="post"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" id="deleteItemId"><button class="btn btn-danger">Supprimer définitivement</button></form></div></div></div></div><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/js/bootstrap.bundle.min.js"></script><script>document.getElementById('deleteModal').addEventListener('show.bs.modal',function(event){document.getElementById('deleteItemName').textContent=event.relatedTarget.dataset.itemName;document.getElementById('deleteItemId').value=event.relatedTarget.dataset.itemId;});</script></main></body></html>
